  plAcc_mainnet_disabled: ['Le réseau principal est fermé sur ce serveur (réglage du serveur).', 'Mainnet is closed on this server (server setting).'],
  plAcc_account_not_flat: ['Ce compte porte déjà des positions ou des ordres en attente. Un agent démarre sur un compte à plat : fermez les positions et annulez les ordres dans le terminal Futures, avec votre clé d’accès.', 'This account already holds positions or resting orders. An agent starts on a flat account: close the positions and cancel the orders in the Futures terminal, with your passkey.'],
  plAcc_mandate_exists: ['Un mandat est déjà en vigueur sur ce compte. Révoquez-le dans Futures → Comptes (ou arrêtez l’agent qui l’utilise) avant d’en préparer un autre.', 'A mandate is already in force on this account. Revoke it in Futures → Accounts (or stop the agent using it) before preparing another.'],
  plFund_no_account: ['Aucun compte de la plateforme : rien à alimenter pour l’instant.', 'No venue account: nothing to fund yet.'],
  plAcc_venue_unreadable: ['Le compte n’a pas pu être lu sur la plateforme : son état est inconnu. Réessayez dans un instant.', 'The account could not be read on the venue: its state is unknown. Try again in a moment.'],
  plGoAccounts: ['Ouvrir Futures → Comptes', 'Open Futures → Accounts'],
  plFundedOk: ['Valeur du compte : {equity} USDC (minimum pour cet agent : {min} USDC).', 'Account value: {equity} USDC (minimum for this agent: {min} USDC).'],
  plFund_unfunded: ['Ce compte n’a jamais reçu de dépôt. La plateforme refuse toute action d’un tel compte (« Must deposit before performing actions ») : l’autorisation elle-même échoue. Alimentez-le d’abord.',
    'This account never received a deposit. The venue refuses every action of such an account (“Must deposit before performing actions”): the authorisation itself fails. Fund it first.'],
  plFund_below_minimum: ['Valeur du compte : {equity} USDC. Il en faut au moins {min} pour cet agent.', 'Account value: {equity} USDC. This agent needs at least {min}.'],
